-- Baseline schema for the Cinema Booking System.
--
-- Columns mirror dk.via.cinema.entity.ScreeningEntity one to one:
--   id           @Id @GeneratedValue(strategy = GenerationType.IDENTITY), Long
--   movie_title  @Column(name = "movie_title", nullable = false), String
--   start_time   @Column(name = "start_time", nullable = false), LocalDateTime
--   room         @Column(nullable = false), String
--
-- String columns use VARCHAR(255) because the entity declares no explicit
-- length, so Hibernate's default column definition is varchar(255).
-- start_time uses TIMESTAMP(6) because LocalDateTime maps to timestamp with
-- precision 6; Hibernate's schema validator compares that type at startup.
CREATE TABLE screenings (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    movie_title VARCHAR(255) NOT NULL,
    start_time  TIMESTAMP(6) NOT NULL,
    room        VARCHAR(255) NOT NULL
);
